import React, { useState, useEffect, useMemo, useCallback } from 'react';
import {
  Dialog,
  DialogContent,
  Box,
  Typography,
  IconButton,
  Chip,
  Grid,
  Card,
  Button,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  List,
  ListItem,
  ListItemButton,
  Divider,
  CircularProgress,
  Alert
} from '@mui/material';
import {
  Close as CloseIcon,
  ExpandMore as ExpandMoreIcon,
  PlayArrow,
  Star,
  CalendarToday,
  Movie,
  Tv
} from '@mui/icons-material';
import { styled } from '@mui/material/styles';
import SeriesPlayer from './SeriesPlayer';
import { getSeriesInfo, getSeriesEpisodes } from '../services/iptvService';

const StyledDialog = styled(Dialog)(({ theme }) => ({
  '& .MuiDialog-paper': {
    backgroundColor: '#1a1a1a',
    color: '#fff',
    maxWidth: '1200px',
    width: '95%',
    maxHeight: '90vh',
    margin: theme.spacing(2),
  },
}));

const HeaderSection = styled(Box)({
  position: 'relative',
  minHeight: '300px',
  background: 'linear-gradient(135deg, #1a1a1a 0%, #2d2d2d 100%)',
  borderRadius: '8px 8px 0 0',
  overflow: 'hidden',
});

const BackdropImage = styled('div')<{ backdrop?: string }>(({ backdrop }) => ({
  position: 'absolute',
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundImage: backdrop ? `url(${backdrop})` : 'none',
  backgroundSize: 'cover',
  backgroundPosition: 'center',
  opacity: 0.3,
  '&::after': {
    content: '""',
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    background: 'linear-gradient(to bottom, rgba(26,26,26,0.4) 0%, rgba(26,26,26,0.9) 100%)',
  },
}));

const HeaderContent = styled(Box)({
  position: 'relative',
  zIndex: 2,
  padding: '24px',
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'flex-end',
});

const SeriesTitle = styled(Typography)({
  fontSize: '2.5rem',
  fontWeight: 700,
  marginBottom: '16px',
  textShadow: '2px 2px 4px rgba(0,0,0,0.8)',
});

const SeriesInfo = styled(Box)({
  display: 'flex',
  alignItems: 'center',
  gap: '16px',
  marginBottom: '16px',
  flexWrap: 'wrap',
});

const InfoChip = styled(Chip)({
  backgroundColor: 'rgba(255, 68, 68, 0.2)',
  color: '#fff',
  border: '1px solid rgba(255, 68, 68, 0.5)',
  '& .MuiChip-icon': {
    color: '#ff4444',
  },
});

const EpisodeItem = styled(ListItem)({
  backgroundColor: '#2d2d2d',
  marginBottom: '8px',
  borderRadius: '8px',
  transition: 'all 0.2s ease',
  '&:hover': {
    backgroundColor: '#3d3d3d',
  },
});

const PlayButton = styled(Button)({
  backgroundColor: '#ff4444',
  color: '#fff',
  '&:hover': {
    backgroundColor: '#ff3333',
  },
  borderRadius: '20px',
  padding: '8px 24px',
  textTransform: 'none',
  fontWeight: 600,
});

const LoadingContainer = styled(Box)({
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  minHeight: '200px',
  flexDirection: 'column',
  gap: '16px',
});

interface Episode {
  id: string;
  title: string;
  episode_num: number;
  season_num: number;
  season_number?: number;
  season?: number;
  container_extension: string;
  info?: {
    plot?: string;
    duration?: string;
    rating?: string;
    releasedate?: string;
    season_num?: number;
  };
}

interface Season {
  season_number: number;
  name: string;
  episode_count: number;
  air_date?: string;
  overview?: string;
  episodes?: Episode[];
}

interface SeriesData {
  seasons: Season[];
  episodes: Episode[];
  allEpisodes?: Episode[];
  info?: {
    name?: string;
    plot?: string;
    cast?: string;
    director?: string;
    genre?: string;
    releasedate?: string;
    rating?: string;
    duration?: string;
    backdrop_path?: string;
    poster_path?: string;
  };
}

interface SeriesModalProps {
  open: boolean;
  onClose: () => void;
  seriesId: string;
  seriesTitle: string;
}

const SeriesModal: React.FC<SeriesModalProps> = ({
  open,
  onClose,
  seriesId,
  seriesTitle,
}) => {
  const [seriesData, setSeriesData] = useState<SeriesData | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [selectedEpisode, setSelectedEpisode] = useState<Episode | null>(null);
  const [expandedSeason, setExpandedSeason] = useState<number | null>(null);
  const [showPlayer, setShowPlayer] = useState(false);

  // Carregar dados da série com debounce
  useEffect(() => {
    if (open && seriesId) {
      // Reset states when opening
      setSeriesData(null);
      setError(null);
      setSelectedEpisode(null);
      setShowPlayer(false);
      setExpandedSeason(null);
      
      // Delay loading to prevent blocking
      const timer = setTimeout(() => {
        loadSeriesData();
      }, 100);
      
      return () => clearTimeout(timer);
    }
  }, [open, seriesId]);

  const loadSeriesData = useCallback(async () => {
    setLoading(true);
    setError(null);
    
    try {
      const user = JSON.parse(localStorage.getItem('iptvUser') || '{}');
      if (!user?.username || !user?.password) {
        setError('Usuário não autenticado');
        return;
      }

      const credentials = { username: user.username, password: user.password };
      
      // Buscar informações da série
      const seriesInfo = await getSeriesInfo(credentials, seriesId);
      
      // Buscar episódios separadamente
      const episodesData = await getSeriesEpisodes(credentials, seriesId);
      
      console.log('=== DEBUG DADOS BRUTOS ===');
      console.log('seriesInfo:', seriesInfo);
      console.log('episodesData:', episodesData);
      
      // Combinar os dados e filtrar apenas episódios da série específica
      let allEpisodes: Episode[] = [];
      
      // Tentar extrair episódios de diferentes estruturas
      if (episodesData?.episodes && Array.isArray(episodesData.episodes)) {
        allEpisodes = episodesData.episodes;
      } else if (episodesData?.seasons && Array.isArray(episodesData.seasons)) {
        // Se os episódios estão dentro das temporadas
        allEpisodes = episodesData.seasons.flatMap((season: any) => season.episodes || []);
      } else if (Array.isArray(episodesData)) {
        allEpisodes = episodesData;
      } else if (seriesInfo?.episodes && Array.isArray(seriesInfo.episodes)) {
        allEpisodes = seriesInfo.episodes;
      } else if (seriesInfo?.seasons && Array.isArray(seriesInfo.seasons)) {
        allEpisodes = seriesInfo.seasons.flatMap((season: any) => season.episodes || []);
      }
      
      console.log('=== DEBUG EPISÓDIOS ===');
      console.log('Série ID:', seriesId);
      console.log('Total de episódios encontrados:', allEpisodes.length);
      console.log('Estrutura dos primeiros 3 episódios:', allEpisodes.slice(0, 3));
      
      // Não filtrar por series_id - manter todos os episódios encontrados
      // pois quando buscamos episódios de uma série específica, todos já pertencem a ela
      
      // Criar temporadas automaticamente se não existirem
      let seasons = seriesInfo?.seasons || episodesData?.seasons || [];
      
      if (!seasons || seasons.length === 0) {
        // Agrupar episódios por temporada
        const seasonMap = new Map();
        
        allEpisodes.forEach((episode: any) => {
          let seasonNum = episode.season_num || episode.season_number || episode.info?.season_num || episode.season;
          
          // Se não encontrou temporada, tentar extrair do título
          if (!seasonNum && episode.title) {
            const seasonMatch = episode.title.match(/S(\d+)E\d+/i) || episode.title.match(/Season\s+(\d+)/i) || episode.title.match(/Temporada\s+(\d+)/i);
            if (seasonMatch) {
              seasonNum = parseInt(seasonMatch[1]);
            }
          }
          
          // Se ainda não encontrou, assumir temporada 1
          if (!seasonNum) {
            seasonNum = 1;
          }
          
          if (!seasonMap.has(seasonNum)) {
            seasonMap.set(seasonNum, {
              season_number: seasonNum,
              name: `Temporada ${seasonNum}`,
              episode_count: 0
            });
          }
          
          const season = seasonMap.get(seasonNum);
          season.episode_count++;
        });
        
        seasons = Array.from(seasonMap.values()).sort((a, b) => a.season_number - b.season_number);
        
        console.log('=== DEBUG TEMPORADAS CRIADAS ===');
        console.log('Temporadas encontradas/criadas:', seasons);
        console.log('Total de temporadas:', seasons.length);
      } else {
        console.log('=== DEBUG TEMPORADAS EXISTENTES ===');
        console.log('Temporadas da API:', seasons);
      }
      
      // Organizar episódios por temporada
      console.log('=== DEBUG EPISÓDIOS FINAIS ===');
      console.log('Total de episódios que serão carregados:', allEpisodes.length);
      
      // Adicionar episódios a cada temporada
      const seasonsWithEpisodes = seasons.map((season: Season) => {
        const seasonEpisodes = (allEpisodes as Episode[]).filter((episode: Episode) => {
          let seasonNum = episode.season_num || episode.season_number || episode.info?.season_num || episode.season;
          
          if (!seasonNum && episode.title) {
            const seasonMatch = episode.title.match(/S(\d+)E\d+/i) || episode.title.match(/Season\s+(\d+)/i) || episode.title.match(/Temporada\s+(\d+)/i);
            if (seasonMatch) {
              seasonNum = parseInt(seasonMatch[1]);
            }
          }
          
          if (!seasonNum) {
            seasonNum = 1;
          }
          
          return seasonNum === season.season_number;
        });
        
        console.log(`Temporada ${season.season_number}: ${seasonEpisodes.length} episódios`);
        
        return {
          ...season,
          episodes: seasonEpisodes
        };
      });
      
      setSeriesData({
        seasons: seasonsWithEpisodes,
        episodes: allEpisodes, // Manter todos os episódios também
        allEpisodes,
        info: seriesInfo?.info || {}
      });
      
      // Expandir primeira temporada por padrão se existir
      const firstSeasonNumber = seasons[0]?.season_number || 1;
      setExpandedSeason(firstSeasonNumber);
    } catch (err) {
      console.error('Erro ao carregar dados da série:', err);
      setError('Erro ao carregar informações da série');
    } finally {
      setLoading(false);
    }
  }, [seriesId]);

  const handleAccordionChange = (seasonNumber: number): void => {
    if (expandedSeason === seasonNumber) {
      setExpandedSeason(null);
    } else {
      setExpandedSeason(seasonNumber);
      // Não modificar o estado dos episódios - deixar que getEpisodesForSeason filtre na renderização
    }
  };

  const handlePlayEpisode = (episode: Episode): void => {
    console.log('=== CLICOU EM ASSISTIR ===');
    console.log('Dados do episódio selecionado:', JSON.stringify(episode, null, 2));
    console.log('Todos os campos do episódio:', Object.keys(episode));
    
    // Verificar se é realmente um episódio ou dados da série
    const episodeId = episode.id || (episode as any).stream_id || (episode as any).series_id;
    const containerExt = episode.container_extension || 'mp4'; // fallback para .mp4
    
    console.log('ID encontrado:', episodeId);
    console.log('Container extension:', containerExt);
    
    if (!episodeId) {
      console.error('ERRO: Não foi possível encontrar ID válido para o episódio!');
      console.error('Campos disponíveis:', Object.keys(episode));
      return;
    }
    
    // Criar uma cópia do episódio com os dados corretos
    const episodeWithId = {
      ...episode,
      id: episodeId,
      container_extension: containerExt
    };
    
    console.log('Episódio processado:', episodeWithId);
    setSelectedEpisode(episodeWithId);
    setShowPlayer(true);
  };

  const handleClosePlayer = () => {
    setShowPlayer(false);
    setSelectedEpisode(null);
  };

  // Memoizar episódios para evitar reprocessamento
  const allEpisodes = useMemo(() => {
    if (!seriesData) return [];

    // Função auxiliar para extrair episódios de qualquer estrutura
    const extractEpisodes = (data: any): Episode[] => {
      if (!data) return [];
      
      // Se já é um array de episódios
      if (Array.isArray(data)) {
        return data.filter((item: any) => item && (item.episode_num !== undefined || item.title));
      }
      
      // Se é um objeto, procurar por arrays dentro dele
      if (typeof data === 'object') {
        for (const key of Object.keys(data)) {
          const value = data[key];
          if (Array.isArray(value) && value.length > 0) {
            const firstItem = value[0];
            if (firstItem && (firstItem.episode_num !== undefined || firstItem.title)) {
              return value;
            }
          }
        }
        
        // Tentar converter o próprio objeto em array
        const values = Object.values(data);
        if (values.length > 0 && values[0] && typeof values[0] === 'object') {
          const firstValue = values[0] as any;
          if (firstValue.episode_num !== undefined || firstValue.title) {
            return values as Episode[];
          }
        }
      }
      
      return [];
    };

    // Procurar episódios em diferentes locais
    return extractEpisodes(seriesData.episodes) ||
           extractEpisodes(seriesData.seasons) ||
           extractEpisodes(seriesData.info) ||
           extractEpisodes(seriesData) ||
           [];
  }, [seriesData]);

  const getEpisodesForSeason = useCallback((seasonNumber: number): Episode[] => {
    if (!seriesData?.seasons) {
      console.log(`Temporada ${seasonNumber}: Nenhuma temporada disponível`);
      return [];
    }

    // Buscar a temporada específica e retornar seus episódios
    const season = seriesData.seasons.find(s => s.season_number === seasonNumber);
    if (!season || !season.episodes) {
      console.log(`Temporada ${seasonNumber}: Temporada não encontrada ou sem episódios`);
      return [];
    }
    
    console.log(`Temporada ${seasonNumber}: ${season.episodes.length} episódios encontrados`);
    return season.episodes;
  }, [seriesData?.seasons]);

  const getNextEpisode = (): Episode | null => {
    if (!selectedEpisode || !seriesData?.episodes) return null;
    
    // Garantir que episodes é um array
    const episodesArray = Array.isArray(seriesData.episodes) 
      ? seriesData.episodes 
      : Object.values(seriesData.episodes);
    
    const currentIndex = episodesArray.findIndex((ep: any) => ep.id === selectedEpisode.id);
    if (currentIndex >= 0 && currentIndex < episodesArray.length - 1) {
      return episodesArray[currentIndex + 1] as Episode;
    }
    return null;
  };

  const getPreviousEpisode = (): Episode | null => {
    if (!selectedEpisode || !seriesData?.episodes) return null;
    
    // Garantir que episodes é um array
    const episodesArray = Array.isArray(seriesData.episodes) 
      ? seriesData.episodes 
      : Object.values(seriesData.episodes);
    
    const currentIndex = episodesArray.findIndex((ep: any) => ep.id === selectedEpisode.id);
    if (currentIndex > 0) {
      return episodesArray[currentIndex - 1] as Episode;
    }
    return null;
  };

  const handleNextEpisode = () => {
    const nextEpisode = getNextEpisode();
    if (nextEpisode) {
      setSelectedEpisode(nextEpisode);
    }
  };

  const handlePreviousEpisode = () => {
    const previousEpisode = getPreviousEpisode();
    if (previousEpisode) {
      setSelectedEpisode(previousEpisode);
    }
  };

  if (showPlayer && selectedEpisode) {
    return (
      <SeriesPlayer
        episode={selectedEpisode}
        seriesTitle={seriesData?.info?.name || seriesTitle}
        onClose={handleClosePlayer}
        onNextEpisode={getNextEpisode() ? handleNextEpisode : undefined}
        onPreviousEpisode={getPreviousEpisode() ? handlePreviousEpisode : undefined}
        hasNextEpisode={!!getNextEpisode()}
        hasPreviousEpisode={!!getPreviousEpisode()}
      />
    );
  }

  return (
    <StyledDialog
      open={open}
      onClose={onClose}
      maxWidth={false}
      fullWidth
    >
      <DialogContent sx={{ p: 0 }}>
        {/* Header */}
        <HeaderSection>
          <BackdropImage backdrop={seriesData?.info?.backdrop_path} />
          <HeaderContent>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
              <Box sx={{ flex: 1 }}>
                <SeriesTitle variant="h3">
                  {seriesData?.info?.name || seriesTitle}
                </SeriesTitle>
                
                <SeriesInfo>
                  {seriesData?.info?.releasedate && (
                    <InfoChip
                      icon={<CalendarToday />}
                      label={new Date(seriesData.info.releasedate).getFullYear()}
                      size="small"
                    />
                  )}
                  
                  {seriesData?.info?.rating && (
                    <InfoChip
                      icon={<Star />}
                      label={seriesData.info.rating || ''}
                      size="small"
                    />
                  )}
                  
                  {seriesData?.seasons && (
                    <InfoChip
                      icon={<Tv />}
                      label={`${seriesData.seasons.length} temporada${seriesData.seasons.length !== 1 ? 's' : ''}`}
                      size="small"
                    />
                  )}
                  
                  {seriesData?.episodes && (
                    <InfoChip
                      icon={<Movie />}
                      label={`${Array.isArray(seriesData.episodes) ? seriesData.episodes.length : Object.keys(seriesData.episodes).length} episódio${(Array.isArray(seriesData.episodes) ? seriesData.episodes.length : Object.keys(seriesData.episodes).length) !== 1 ? 's' : ''}`}
                      size="small"
                    />
                  )}
                  
                  {seriesData?.info?.genre && (
                    <InfoChip
                      label={seriesData.info.genre}
                      size="small"
                    />
                  )}
                </SeriesInfo>
                
                {seriesData?.info?.plot && (
                  <Typography
                    variant="body1"
                    sx={{
                      opacity: 0.9,
                      lineHeight: 1.6,
                      maxWidth: '800px',
                      textShadow: '1px 1px 2px rgba(0,0,0,0.8)',
                    }}
                  >
                    {seriesData.info.plot}
                  </Typography>
                )}
              </Box>
              
              <IconButton
                onClick={onClose}
                sx={{
                  color: '#fff',
                  backgroundColor: 'rgba(0, 0, 0, 0.5)',
                  '&:hover': {
                    backgroundColor: 'rgba(0, 0, 0, 0.7)',
                  },
                }}
              >
                <CloseIcon />
              </IconButton>
            </Box>
          </HeaderContent>
        </HeaderSection>
        
        {/* Content */}
        <Box sx={{ p: 3 }}>
          {loading && (
            <LoadingContainer>
              <CircularProgress size={60} sx={{ color: '#ff4444' }} />
              <Typography variant="h6">Carregando episódios...</Typography>
            </LoadingContainer>
          )}
          
          {error && (
            <Alert severity="error" sx={{ mb: 2 }}>
              {error}
            </Alert>
          )}
          
          {seriesData && (
            <Box>
              {/* Cast and Crew */}
              {(seriesData.info?.cast || seriesData.info?.director) && (
                <Box sx={{ mb: 4 }}>
                  <Typography variant="h6" sx={{ mb: 2, color: '#ff4444' }}>
                    Elenco e Equipe
                  </Typography>
                  <Grid container spacing={2}>
                    {seriesData.info.cast && (
                      <Grid item xs={12} md={6}>
                        <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                          Elenco:
                        </Typography>
                        <Typography variant="body2" sx={{ opacity: 0.8 }}>
                          {seriesData.info.cast}
                        </Typography>
                      </Grid>
                    )}
                    {seriesData.info.director && (
                      <Grid item xs={12} md={6}>
                        <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                          Direção:
                        </Typography>
                        <Typography variant="body2" sx={{ opacity: 0.8 }}>
                          {seriesData.info.director}
                        </Typography>
                      </Grid>
                    )}
                  </Grid>
                  <Divider sx={{ mt: 3, backgroundColor: 'rgba(255, 255, 255, 0.1)' }} />
                </Box>
              )}
              
              {/* Seasons and Episodes */}
              <Typography variant="h6" sx={{ mb: 3, color: '#ff4444' }}>
                Temporadas e Episódios
              </Typography>
              
              {seriesData.seasons?.map((season) => {
                const episodes = getEpisodesForSeason(season.season_number);
                
                return (
                  <Accordion
                    key={season.season_number}
                    expanded={expandedSeason === season.season_number}
                    onChange={() => handleAccordionChange(season.season_number)}
                    sx={{
                      backgroundColor: '#2d2d2d',
                      color: '#fff',
                      mb: 2,
                      '&:before': {
                        display: 'none',
                      },
                      '& .MuiAccordionSummary-root': {
                        backgroundColor: '#3d3d3d',
                        '&:hover': {
                          backgroundColor: '#4d4d4d',
                        },
                      },
                    }}
                  >
                    <AccordionSummary
                      expandIcon={<ExpandMoreIcon sx={{ color: '#fff' }} />}
                    >
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%' }}>
                        <Typography variant="h6" sx={{ fontWeight: 600 }}>
                          {season.name || `Temporada ${season.season_number}`}
                        </Typography>
                        <Chip
                          label={`${episodes.length} episódio${episodes.length !== 1 ? 's' : ''}`}
                          size="small"
                          sx={{
                            backgroundColor: 'rgba(255, 68, 68, 0.2)',
                            color: '#fff',
                            border: '1px solid rgba(255, 68, 68, 0.5)',
                          }}
                        />
                        {season.air_date && (
                          <Typography variant="body2" sx={{ opacity: 0.7, ml: 'auto' }}>
                            {new Date(season.air_date).getFullYear()}
                          </Typography>
                        )}
                      </Box>
                    </AccordionSummary>
                    
                    <AccordionDetails sx={{ p: 0 }}>
                      {season.overview && (
                        <Box sx={{ p: 2, borderBottom: '1px solid rgba(255, 255, 255, 0.1)' }}>
                          <Typography variant="body2" sx={{ opacity: 0.8 }}>
                            {season.overview}
                          </Typography>
                        </Box>
                      )}
                      
                      <List sx={{ p: 0 }}>
                        {episodes.map((episode, index) => (
                          <React.Fragment key={episode.id || index}>
                            {index > 0 && <Divider sx={{ backgroundColor: 'rgba(255, 255, 255, 0.1)' }} />}
                            <EpisodeItem disablePadding>
                              <ListItemButton
                                onClick={() => handlePlayEpisode(episode)}
                                sx={{
                                  py: 2,
                                  '&:hover': {
                                    backgroundColor: 'rgba(255, 68, 68, 0.1)'
                                  }
                                }}
                              >
                                <Grid container spacing={2} alignItems="center">
                                  <Grid item xs={12} sm={8}>
                                    <Typography variant="subtitle1" sx={{ fontWeight: 500 }}>
                                      {episode.title || `Episódio ${episode.episode_num}`}
                                    </Typography>
                                    {episode.info?.plot && (
                                      <Typography
                                        variant="body2"
                                        sx={{
                                          color: 'rgba(255, 255, 255, 0.7)',
                                          mt: 0.5,
                                          display: '-webkit-box',
                                          WebkitLineClamp: 2,
                                          WebkitBoxOrient: 'vertical',
                                          overflow: 'hidden'
                                        }}
                                      >
                                        {episode.info.plot}
                                      </Typography>
                                    )}
                                  </Grid>
                                  
                                  <Grid item xs={12} sm={4} sx={{ textAlign: { sm: 'right' } }}>
                                    <PlayButton
                                      startIcon={<PlayArrow />}
                                      size="small"
                                      onClick={(e) => {
                                        e.stopPropagation();
                                        handlePlayEpisode(episode);
                                      }}
                                    >
                                      Assistir
                                    </PlayButton>
                                  </Grid>
                                </Grid>
                              </ListItemButton>
                            </EpisodeItem>
                          </React.Fragment>
                        ))}
                      </List>
                    </AccordionDetails>
                  </Accordion>
                );
              })}
            </Box>
          )}
        </Box>
      </DialogContent>
    </StyledDialog>
  );
};

export default SeriesModal;